const fs = require('fs');
const path = require('path');

// Browser configuration is public. Never embed a Mapbox secret token.
const token = (process.env.MAPBOX_ACCESS_TOKEN || '').trim();
if (token && !token.startsWith('pk.')) {
  console.error('MAPBOX_ACCESS_TOKEN must be a public Mapbox token (pk.*), never a secret token.');
  process.exit(1);
}

const output = path.join(__dirname, '../src/environments/environment.generated.ts');
fs.writeFileSync(output,
  '// Generated by npm run config:env. Do not commit.\n' +
  'export const mapboxAuth = ' + JSON.stringify(token) + ';\n');
